CREATE TABLE IF NOT EXISTS sop_location (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 code VARCHAR(64) NOT NULL UNIQUE,
 name VARCHAR(255) NOT NULL,
 status TINYINT NOT NULL DEFAULT 0 CHECK(status IN(0,1,2)),
 description VARCHAR(2000),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id)
);
CREATE TABLE IF NOT EXISTS sop_station (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, location VARCHAR(255), location_id BIGINT, ip_address VARCHAR(45), active_ip VARCHAR(45) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN ip_address ELSE NULL END), UNIQUE(active_ip), FOREIGN KEY(location_id) REFERENCES sop_location(id), owner_user_id BIGINT, status TINYINT NOT NULL DEFAULT 0 CHECK(status IN(0,1,2)), description VARCHAR(2000), FOREIGN KEY(owner_user_id) REFERENCES sys_user(id),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sop_resource_model (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, type_code VARCHAR(64) NOT NULL, model VARCHAR(128), specification VARCHAR(1000), unit VARCHAR(32) NOT NULL, status TINYINT NOT NULL DEFAULT 0 CHECK(status IN(0,1,2)), description VARCHAR(2000),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sop_resource_device (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, model_id BIGINT NOT NULL, serial_number VARCHAR(128), station_id BIGINT, owner_user_id BIGINT, status TINYINT NOT NULL DEFAULT 0 CHECK(status IN(0,1,2)), description VARCHAR(2000), FOREIGN KEY(model_id) REFERENCES sop_resource_model(id), FOREIGN KEY(station_id) REFERENCES sop_station(id), FOREIGN KEY(owner_user_id) REFERENCES sys_user(id),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sop_device_connection (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device_id BIGINT NOT NULL UNIQUE, transport VARCHAR(16) NOT NULL CHECK(transport IN('network','usb','serial','none')), protocol VARCHAR(32) NOT NULL, host VARCHAR(255), port INT CHECK(port BETWEEN 1 AND 65535), path VARCHAR(1000), rtsp_url VARCHAR(1300), host_key VARCHAR(128), device_key VARCHAR(255), enabled TINYINT NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), FOREIGN KEY(device_id) REFERENCES sop_resource_device(id),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sop_step_resource_requirement (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, step_id BIGINT NOT NULL, model_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, type_code VARCHAR(64) NOT NULL, model VARCHAR(128), specification VARCHAR(1000), unit VARCHAR(32) NOT NULL, quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 9999), description VARCHAR(2000), sort_order INT NOT NULL, UNIQUE(step_id,model_id), FOREIGN KEY(step_id) REFERENCES sop_step(id) ON DELETE CASCADE, FOREIGN KEY(model_id) REFERENCES sop_resource_model(id));
CREATE TABLE IF NOT EXISTS sop_task (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, subproject_id BIGINT NOT NULL, station_id BIGINT, owner_user_id BIGINT NOT NULL, sort_order INT NOT NULL DEFAULT 0 CHECK(sort_order>=0), status TINYINT NOT NULL DEFAULT 0 CHECK(status IN(0,1,2)), description VARCHAR(2000), FOREIGN KEY(subproject_id) REFERENCES sop_subproject(id), FOREIGN KEY(station_id) REFERENCES sop_station(id), FOREIGN KEY(owner_user_id) REFERENCES sys_user(id),
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 version INT NOT NULL DEFAULT 0, deleted_at DATETIME(3) NULL,
 FOREIGN KEY(created_by) REFERENCES sys_user(id), FOREIGN KEY(updated_by) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sop_task_standard (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT NOT NULL, sop_id BIGINT NOT NULL, revision_id BIGINT NOT NULL, active TINYINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_by BIGINT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(task_id) REFERENCES sop_task(id), FOREIGN KEY(sop_id,revision_id) REFERENCES sop_revision(sop_id,id), FOREIGN KEY(created_by) REFERENCES sys_user(id));
ALTER TABLE sop_step ADD COLUMN IF NOT EXISTS workplace_requirements VARCHAR(2000);

CREATE TABLE IF NOT EXISTS sop_task_content(task_id BIGINT PRIMARY KEY REFERENCES sop_task(id),sop_id BIGINT NOT NULL UNIQUE REFERENCES sop_document(id),created_by BIGINT NOT NULL REFERENCES sys_user(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

-- Execution tables for cross-module reference guards.
-- Execution module v1, MySQL 8.4 / InnoDB.
-- Select sop_dev explicitly. Requires existing user/project/SOP/resource tables.
-- Additive migration; no existing data is deleted or rewritten. Run the WHOLE file.

CREATE TABLE IF NOT EXISTS sop_execution (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 request_key VARCHAR(64) NOT NULL,
 task_id BIGINT NOT NULL, project_id BIGINT NOT NULL, subproject_id BIGINT NOT NULL,
 station_id BIGINT NOT NULL, active_station_id BIGINT NULL,
 sop_id BIGINT NOT NULL, revision_id BIGINT NOT NULL,
 operator_id BIGINT NOT NULL,
 product_code VARCHAR(128) NOT NULL,
 task_name VARCHAR(128) NOT NULL, project_name VARCHAR(128) NOT NULL,
 subproject_name VARCHAR(128) NOT NULL, station_name VARCHAR(255) NOT NULL,
 operator_name VARCHAR(128) NOT NULL, revision_no INT NOT NULL,
 content_snapshot CLOB NOT NULL,
 status TINYINT NOT NULL DEFAULT 0,
 version INT NOT NULL DEFAULT 0,
 started_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 ended_at DATETIME(3) NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 CONSTRAINT uk_execution_request UNIQUE(operator_id,request_key),
 CONSTRAINT uk_execution_product UNIQUE(task_id,product_code),
 CONSTRAINT uk_execution_station UNIQUE(active_station_id),
 CONSTRAINT ck_execution_status CHECK(status IN(0,1,2,3)),
 CONSTRAINT ck_execution_active CHECK((status IN(0,1) AND active_station_id IS NOT NULL AND active_station_id=station_id) OR (status IN(2,3) AND active_station_id IS NULL)),
 FOREIGN KEY(task_id) REFERENCES sop_task(id), FOREIGN KEY(project_id) REFERENCES sop_project(id),
 FOREIGN KEY(subproject_id) REFERENCES sop_subproject(id), FOREIGN KEY(station_id) REFERENCES sop_station(id),
 FOREIGN KEY(operator_id) REFERENCES sys_user(id), FOREIGN KEY(sop_id,revision_id) REFERENCES sop_revision(sop_id,id),
 INDEX ix_execution_started(started_at,id), INDEX ix_execution_station(station_id,status)
);
CREATE TABLE IF NOT EXISTS sop_execution_step (
 execution_id BIGINT NOT NULL, position INT NOT NULL, step_id BIGINT NOT NULL,
 confirmed_at DATETIME(3) NULL, confirmed_by BIGINT NULL,
 PRIMARY KEY(execution_id,position), UNIQUE(execution_id,step_id),
 FOREIGN KEY(execution_id) REFERENCES sop_execution(id), FOREIGN KEY(confirmed_by) REFERENCES sys_user(id)
);
CREATE TABLE IF NOT EXISTS sop_execution_event (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, execution_id BIGINT NOT NULL,
 action VARCHAR(16) NOT NULL, reason VARCHAR(2000) NULL, actor_id BIGINT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(execution_id) REFERENCES sop_execution(id), FOREIGN KEY(actor_id) REFERENCES sys_user(id),
 INDEX ix_execution_event(execution_id,id)
);

